        array("id" => "s2012e9", "season" => 2012, "number" => 9, "name" => "The Man Named Kisame", "airdate" => "23 Feb 2012", "runtime" => 30, "rating" => 8, "summary" => "Kisame's escape is prevented thanks to Guy's efforts. Aoba enters Kisame's mind to gather intel on the Akatsuki.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/497/1244771.jpg"),
        array("id" => "s2012e10", "season" => 2012, "number" => 10, "name" => "The Angelic Herald of Death", "airdate" => "1 Mar 2012", "runtime" => 30, "rating" => 8.8, "summary" => "Madara appears in the Hidden Rain Village seeking the corpse of Nagato and his Rinnegan.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/497/1244802.jpg"),
        array("id" => "s2012e11", "season" => 2012, "number" => 11, "name" => "The Bridge to Peace", "airdate" => "8 Mar 2012", "runtime" => 30, "rating" => 8.9, "summary" => "Madara uses the forbidden jutsu Izanagi to escape Konan's Paper Bomb trap.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1245070.jpg"),
        array("id" => "s2012e12", "season" => 2012, "number" => 12, "name" => "The Super Secret S-Rank Mission", "airdate" => "15 Mar 2012", "runtime" => 30, "rating" => 8.1, "summary" => "The Leaf and Cloud ninja prepare to relocate Naruto and Bee, as the Akatsuki may already have knowledge of their location. Aoba assigns Naruto an S-rank mission to distract him from learning about their true mission: keeping the two Jinchuriki hidden from the…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1245098.jpg"),
        array("id" => "s2012e13", "season" => 2012, "number" => 13, "name" => "The Artist Returns", "airdate" => "22 Mar 2012", "runtime" => 30, "rating" => 7.9, "summary" => "Kabuto and a reanimated Deidara attempt to grab hold of the jinchuriki, but are stopped by the Tsuchikage, who has come to protect Naruto.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1245190.jpg"),
