        array("id" => "s2012e16", "season" => 2012, "number" => 16, "name" => "Rivals", "airdate" => "12 Apr 2012", "runtime" => 30, "rating" => 7.7, "summary" => "During the Chunin Exam, Sasuke witnesses Naruto's growth as a shinobi", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1245445.jpg"),
        array("id" => "s2012e17", "season" => 2012, "number" => 17, "name" => "Rift", "airdate" => "19 Apr 2012", "runtime" => 30, "rating" => 8, "summary" => "Sasuke's defeat to Gaara, and later Itachi, forces him to realize that he is not strong enough to get revenge against his older brother.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1245446.jpg"),
        array("id" => "s2012e18", "season" => 2012, "number" => 18, "name" => "Parting", "airdate" => "26 Apr 2012", "runtime" => 30, "rating" => 8.6, "summary" => "Naruto is determined to save Sasuke, who has deserted the Hidden Leaf.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1245451.jpg"),
        array("id" => "s2012e19", "season" => 2012, "number" => 19, "name" => "For My Friend", "airdate" => "3 May 2012", "runtime" => 30, "rating" => 8.6, "summary" => "The Allied Shinobi Forces are on standby, ready to confront Madara's army of reanimated shinobi and 100,000 White Zetsu. But distrust still exists among the Allied Shinobi Forces, who were once sworn enemies until recently.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1245838.jpg"),
