        array("id" => "s2012e21", "season" => 2012, "number" => 21, "name" => "Sai and Shin", "airdate" => "17 May 2012", "runtime" => 30, "rating" => 9.3, "summary" => "The Allied Shinobi Forces' commando unit engages with the Akatsuki in the first wave of battle.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1245851.jpg"),
        array("id" => "s2012e22", "season" => 2012, "number" => 22, "name" => "The Secret of the Impure World Reincarnatio", "airdate" => "24 May 2012", "runtime" => 30, "rating" => 8.8, "summary" => "Under the guidance of Killer Bee, Naruto enters the final stage of training to master the Tailed Beast Bomb, a Jinchuriki's most powerful technique.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1245854.jpg"),
        array("id" => "s2012e23", "season" => 2012, "number" => 23, "name" => "An Old Nemesis Returns", "airdate" => "31 May 2012", "runtime" => 30, "rating" => 9, "summary" => "The commando unit is in hot water as they engage the reanimated Kekkei Genkai shinobi, which include Zabuza Momochi and Haku. Luckily, Kakashi and his unit arrive in time to assist them.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1245860.jpg"),
        array("id" => "s2012e24", "season" => 2012, "number" => 24, "name" => "The First and Last Opponent", "airdate" => "7 Jun 2012", "runtime" => 30, "rating" => 8.8, "summary" => "Kakashi and his unit devise a strategy to take on the Kekkei Genkai shinobi, but it's foiled by Kabuto, who uses the Reanimation Jutsu to summon the most powerful members of the Seven Ninja Swordsmen of the Mist.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1246200.jpg"),
        array("id" => "s2012e25", "season" => 2012, "number" => 25, "name" => "The Brilliant Military Advisor of the Hidden Leaf", "airdate" => "21 Jun 2012", "runtime" => 30, "rating" => 9.3, "summary" => "The Akatsuki dispatch an army of powerful reanimated shinobi and White Zetsu across the war zone, causing chaos within the Allied Shinobi Forces' chain of command.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1246207.jpg"),
        array("id" => "s2012e26", "season" => 2012, "number" => 26, "name" => "Battleground!", "airdate" => "28 Jun 2012", "runtime" => 30, "rating" => 8.3, "summary" => "As Darui and his First Company engage an army of White Zetsu, the remaining forces must deal with reanimated shinobi.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1246219.jpg"),
        array("id" => "s2012e27", "season" => 2012, "number" => 27, "name" => "No-Good Words", "airdate" => "5 Jul 2012", "runtime" => 30, "rating" => 8.1, "summary" => "Atsui, Samui, and Darui face off against Kinkaku and Ginkaku, the legendary brothers from the Hidden Cloud, feared even by the Raikage.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1246379.jpg"),
        array("id" => "s2012e28", "season" => 2012, "number" => 28, "name" => "Golden Bonds", "airdate" => "19 Jul 2012", "runtime" => 30, "rating" => 8.6, "summary" => "Darui manages to seal away Ginkaku. Fueled by the rage of losing his brother, Kinkaku transforms into a monster that resembles a jinchuriki's Tailed Beast State.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1246555.jpg"),
        array("id" => "s2012e29", "season" => 2012, "number" => 29, "name" => "Road to Sakura", "airdate" => "26 Jul 2012", "runtime" => 30, "rating" => 7.3, "summary" => "Ino sees Sakura falling from the sky. Although she manages to save her, the shock of the fall has left Sakura with amnesia.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1246969.jpg"),
        array("id" => "s2012e30", "season" => 2012, "number" => 30, "name" => "Mifune vs. Hanzō", "airdate" => "2 Aug 2012", "runtime" => 30, "rating" => 7.3, "summary" => "Kankuro's Commando Unit is cornered by Hanzo's poison attack. Fortunately, Mifune and his Fifth Company arrive in time to provide assistance.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1247040.jpg"),
        array("id" => "s2012e31", "season" => 2012, "number" => 31, "name" => "True Kindness", "airdate" => "9 Aug 2012", "runtime" => 30, "rating" => 8.1, "summary" => "The Ino-Shika-Cho trio is ordered by Shikaku to take down the reanimated Asuma. Remembering Asuma's final words, Shikamaru and Ino are determined to stop their former teacher.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1247416.jpg"),
        array("id" => "s2012e32", "season" => 2012, "number" => 32, "name" => "The Complete Ino-Shika-Chō Formation", "airdate" => "9 Aug 2012", "runtime" => 30, "rating" => 8.1, "summary" => "Choji is unable to attack Asuma and loses his will to fight. Ino and Shikamaru try to snap Choji out of his paralysis.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1247422.jpg"),
        array("id" => "s2012e33", "season" => 2012, "number" => 33, "name" => "A Message from the Heart", "airdate" => "16 Aug 2012", "runtime" => 30, "rating" => 9.4, "summary" => "While training in Chakra Mode, Naruto senses the presence of the Nine Tails' chakra seeping from Kinkaku outside.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/498/1247428.jpg"),
        array("id" => "s2012e34", "season" => 2012, "number" => 34, "name" => "Attack of the Gedō Statue", "airdate" => "23 Aug 2012", "runtime" => 30, "rating" => 8.6, "summary" => "The Allied Shinobi Forces are on the verge of winning the war when Madara Uchiha appears. Madara summons the giant Gedo Statue and unleashes its devastating power.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/499/1248164.jpg"),
        array("id" => "s2012e35", "season" => 2012, "number" => 35, "name" => "Unison Sign", "airdate" => "30 Aug 2012", "runtime" => 30, "rating" => 8.3, "summary" => "Naruto and Killer Bee rush to the battlefield when Nine Tails suddenly speaks to Naruto inside his mind.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/499/1248170.jpg"),
        array("id" => "s2012e36", "season" => 2012, "number" => 36, "name" => "Medic Ninja in Danger", "airdate" => "6 Sep 2012", "runtime" => 30, "rating" => 8.3, "summary" => "Over at the Medical Unit camp, Sakura and the other medic ninja work nonstop to treat the wounded. Neji is there to recover from overusing his Byakugan.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/499/1248488.jpg"),
        array("id" => "s2012e37", "season" => 2012, "number" => 37, "name" => "White Zetsu's Trap", "airdate" => "13 Sep 2012", "runtime" => 30, "rating" => 7.3, "summary" => "Kiba, Shino, and Hinata are sent to investigate an area where the Akatsuki are supposedly getting through. There, the three are ambushed by a White Zetsu and get separated.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/499/1248987.jpg"),
        array("id" => "s2012e38", "season" => 2012, "number" => 38, "name" => "Aesthetics of an Artist", "airdate" => "20 Sep 2012", "runtime" => 30, "rating" => 7, "summary" => "Back at the Fifth Company's camp, Kurotsuchi attempts to negotiate with the captive Deidara to find out Kabuto's location, but is quickly rebuffed.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/499/1249123.jpg"),
        array("id" => "s2012e39", "season" => 2012, "number" => 39, "name" => "The Allied Mom Force!!", "airdate" => "27 Sep 2012", "runtime" => 30, "rating" => 7.8, "summary" => "With many of the shinobi away serving in the Fourth Great Ninja War, the Leaf Village is left with just the mothers and children to protect it. Konohamaru is eager to guard the village but is quickly discouraged by the adults who tell him to just go about his…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/499/1249486.jpg"),
        array("id" => "s2012e40", "season" => 2012, "number" => 40, "name" => "The Secret Origin of the Ultimate Tag Team!!", "airdate" => "4 Oct 2012", "runtime" => 30, "rating" => 8.2, "summary" => "Tsunade and the Raikage arrive to prevent Naruto and Killer Bee from joining the battle. But the two Kage fail to convince the Jinchuriki to turn back, forcing the Raikage to use extreme force.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/499/1249509.jpg"),
        array("id" => "s2012e41", "season" => 2012, "number" => 41, "name" => "Two Suns!!", "airdate" => "11 Oct 2012", "runtime" => 30, "rating" => 8.3, "summary" => "Fourth Raikage Ay attacks Naruto in an attempt to prevent the Jinchuriki from falling into Madara's hands. Ay is unwilling to listen to either Tsunade or Killer Bee's pleas to change his mind.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/499/1249513.jpg"),
        array("id" => "s2012e42", "season" => 2012, "number" => 42, "name" => "The Helmet Splitter: Jinin Akebino!", "airdate" => "18 Oct 2012", "runtime" => 30, "rating" => 9, "summary" => "Kakashi assigns Sai to take over for the Sealing Corps, who are recovering from sealing the reanimated shinobi. But Sai is not sure if he can handle the responsibility. Soon afterwards, the Third Company is attacked by Jinin Akebino.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/500/1250449.jpg"),
        array("id" => "s2012e43", "season" => 2012, "number" => 43, "name" => "User of the Scorch Release: Pakura of the Sand!", "airdate" => "25 Oct 2012", "runtime" => 30, "rating" => 8.8, "summary" => "A group of Allied Shinobi, including Omoi and Maki of the Sand, battle against several reanimated enemies. Maki recognizes one of them as Pakura, her former master who was a Sand Village hero.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/500/1250768.jpg"),
        array("id" => "s2012e44", "season" => 2012, "number" => 44, "name" => "Things You Can't Get Back", "airdate" => "1 Nov 2012", "runtime" => 30, "rating" => 7, "summary" => "Still coping with the loss of her loved ones, Tsunade indulges in gambling and drinking. Around the same time, the Raikage Ay and his men are on a mission to steal a scroll from a certain village.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/500/1250809.jpg"),
        array("id" => "s2012e45", "season" => 2012, "number" => 45, "name" => "One Worth Betting On", "airdate" => "1 Nov 2012", "runtime" => 30, "rating" => 8, "summary" => "The Raikage Ay and his team suffer critical injuries during an enemy attack. Unwilling to sacrifice any more of his men, Ay seeks medical help from Tsunade, who just happens to be in the area.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/500/1251245.jpg"),
        array("id" => "s2012e46", "season" => 2012, "number" => 46, "name" => "Danger: Jinpachi and Kushimaru!", "airdate" => "8 Nov 2012", "runtime" => 30, "rating" => 8.2, "summary" => "Kakashi races to the scene where the Seven Ninja Swordsmen Kushimaru Kuriarare and Jinpachi Munashi were last sighted. Enraged by the carnage they've left behind, Kakashi teams up with Might Guy.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/500/1251528.jpg"),
        array("id" => "s2012e47", "season" => 2012, "number" => 47, "name" => "The Lightning Blade: Ameyuri Ringo", "airdate" => "15 Nov 2012", "runtime" => 30, "rating" => 8, "summary" => "Omoi's unit is attacked by Ameyuri Ringo of the Seven Ninja Swordsmen and loses one of Omoi's men. Omoi attempts to avenge his comrade, but Nurui orders everyone to retreat.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/500/1251777.jpg"),
        array("id" => "s2012e48", "season" => 2012, "number" => 48, "name" => "Power - Episode 1", "airdate" => "22 Nov 2012", "runtime" => 30, "rating" => 8, "summary" => "Naruto and his team are assigned a mission to identify and hunt down the perpetrator of the Tonika Village massacre. It's been a while since Naruto has had a mission, and he's pumped to take it on.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/500/1251782.jpg"),
        array("id" => "s2012e49", "season" => 2012, "number" => 49, "name" => "Power - Episode 2", "airdate" => "29 Nov 2012", "runtime" => 30, "rating" => 8.4, "summary" => "While investigating the village near Tonika, Kabuto confronts Naruto. An epic battle erupts as Kabuto uses the forbidden Reanimation Jutsu against Naruto. In the meantime, Dokku and the five survivors lie low at the village.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/500/1251787.jpg"),
        array("id" => "s2012e50", "season" => 2012, "number" => 50, "name" => "Power - Episode 3", "airdate" => "6 Dec 2012", "runtime" => 30, "rating" => 8.2, "summary" => "Naruto and Sakura decide to stay at Shiseru's house overnight to help watch over the survivors. Although the children cry and miss their deceased parents, Dokku and Shiseru try hard to bring everyone together as a new family.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/500/1251905.jpg"),
        array("id" => "s2012e51", "season" => 2012, "number" => 51, "name" => "Power - Episode 4", "airdate" => "13 Dec 2012", "runtime" => 30, "rating" => 8, "summary" => "A clone possessing the Nine Tails' chakra emerges from Naruto's body. Seeking more power, the clone goes on a rampage, destroying everything in its path.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/500/1252210.jpg"),
        array("id" => "s2012e52", "season" => 2012, "number" => 52, "name" => "Power - Episode 5", "airdate" => "20 Dec 2012", "runtime" => 30, "rating" => 8.2, "summary" => "After their defeat by the Nine Tails' clone, Naruto and Dokku are taken captive by Kabuto.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/500/1252224.jpg"),
    )),
    array("number" => 2013, "name" => "#515 - #563", "rating" => 7.7, "episodes" => array(
        array("id" => "s2013e1", "season" => 2013, "number" => 1, "name" => "Power - Episode Final", "airdate" => "10 Jan 2013", "runtime" => 30, "rating" => 7.8, "summary" => "The legendary Ama no Hoko imbues the Nine Tails' clone with enough power to destroy the world. Naruto is overcome by its immense power and lies unconscious.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/500/1252231.jpg"),
        array("id" => "s2013e2", "season" => 2013, "number" => 2, "name" => "Naruto Enters the Battle!", "airdate" => "17 Jan 2013", "runtime" => 30, "rating" => 8.5, "summary" => "Naruto makes his entrance onto the battlefield and uses his sensory powers to detect and destroy the transformed White Zetsu clones. During the battle, Shikaku updates Naruto with what they currently know on Madara.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/500/1252248.jpg"),
        array("id" => "s2013e3", "season" => 2013, "number" => 3, "name" => "A Father's Hope, A Mother's Love", "airdate" => "24 Jan 2013", "runtime" => 30, "rating" => 8.4, "summary" => "Gaara leads the Fourth Company into battle against the previous Kage, including his father, the late Fourth Kazekage. The Fourth Kazekage attacks Gaara in order to determine if his son is truly worthy to be the current Kazekage.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/500/1252253.jpg"),
        array("id" => "s2013e4", "season" => 2013, "number" => 4, "name" => "Contact! Naruto vs. Itachi", "airdate" => "31 Jan 2013", "runtime" => 30, "rating" => 8, "summary" => "Naruto and Killer Bee engage in battle against the reanimated Itachi Uchiha and Nagato. Itachi learns from Naruto that Sasuke has chosen the path of vengeance.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/500/1252268.jpg"),
        array("id" => "s2013e5", "season" => 2013, "number" => 5, "name" => "The Acknowledged One", "airdate" => "7 Feb 2013", "runtime" => 30, "rating" => 8.4, "summary" => "Itachi uses the ultimate genjutsu technique Koto Amatsukami to free himself from the Reanimation Jutsu. Itachi then joins Naruto and Killer Bee to fight Nagato, who is still under Kabuto's control.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/500/1252468.jpg"),
        array("id" => "s2013e6", "season" => 2013, "number" => 6, "name" => "The Mizukage, the Giant Clam, and the Mirage", "airdate" => "14 Feb 2013", "runtime" => 30, "rating" => 8, "summary" => "The Fourth Company continue their fight against the reanimated Kage. Gaara and Ohnoki team up to hold off Second Tsuchikage Mu, while the remaining shinobi take on the Second Mizukage, who is willing to be sealed away.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/500/1252478.jpg"),
        array("id" => "s2013e7", "season" => 2013, "number" => 7, "name" => "Paradox", "airdate" => "21 Feb 2013", "runtime" => 30, "rating" => 8, "summary" => "Temari leads the attack on the Third Raikage using Wind Style, but even her strongest jutsu is not enough to penetrate the Raikage's invincible armor.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/501/1252882.jpg"),
        array("id" => "s2013e8", "season" => 2013, "number" => 8, "name" => "Terror: Steaming Danger Tyranny", "airdate" => "28 Feb 2013", "runtime" => 30, "rating" => 7.6, "summary" => "Gaara and Ohnoki manage to overcome the Second Mizukage's mirage attack. Having taken an interest in Gaara, the Second Mizukage decides to further test the young Kage's skills.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/501/1252886.jpg"),
        array("id" => "s2013e9", "season" => 2013, "number" => 9, "name" => "Ghosts from the Past", "airdate" => "7 Mar 2013", "runtime" => 30, "rating" => 7.4, "summary" => "Shikamaru, Choji, Neji, and Kiba find themselves up against some familiar faces from the past. The Sound Ninja Four have been brought back by Kabuto's Reanimation Jutsu, and they are ready to seek vengeance.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/501/1254008.jpg"),
        array("id" => "s2013e10", "season" => 2013, "number" => 10, "name" => "The Underworld Transfer Jutsu", "airdate" => "14 Mar 2013", "runtime" => 30, "rating" => 7.3, "summary" => "Shikamaru, Neji, Choji, and Kiba succeed in defeating the Sound Ninja Four. But the enemy uses the Underworld Transfer Jutsu to trap the Leaf shinobi's souls inside a barrier.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/501/1254023.jpg"),
        array("id" => "s2013e11", "season" => 2013, "number" => 11, "name" => "The Vengeful", "airdate" => "21 Mar 2013", "runtime" => 30, "rating" => 7.8, "summary" => "Time is running out for the Leaf shinobi whose souls are trapped inside the Sound Four's barrier. Ino and Shino exhaust their own chakra to keep their friends alive.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/502/1255810.jpg"),
        array("id" => "s2013e12", "season" => 2013, "number" => 12, "name" => "The Heart's Eye", "airdate" => "28 Mar 2013", "runtime" => 30, "rating" => 7.8, "summary" => "Hinata defends Neji from a White Zetsu clone while he's recovering from an earlier fight. She then remembers the time Neji protected her the same way after she temporarily lost her sight.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/502/1257022.jpg"),
        array("id" => "s2013e13", "season" => 2013, "number" => 13, "name" => "Fade into the Moonlight", "airdate" => "4 Apr 2013", "runtime" => 30, "rating" => 7.4, "summary" => "Three years ago, Leaf Anbu Yugao Uzuki lost her lover Hayate Gekko in battle. Unable to cope with his death, Yugao has since left the Anbu and joined the Medical Corps. Meanwhile, Kabuto has reanimated Hayate.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/503/1257514.jpg"),
        array("id" => "s2013e14", "season" => 2013, "number" => 14, "name" => "Night of the Crescent Moon", "airdate" => "11 Apr 2013", "runtime" => 30, "rating" => 7.3, "summary" => "Yugao is ordered by Sukui to track down the reanimated Hayate. Still shaken by her lover's unexpected return as an enemy, Yugao manages to catch up to Hayate and his men.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/503/1258630.jpg"),
        array("id" => "s2013e15", "season" => 2013, "number" => 15, "name" => "An A-Rank Mission: The Contest", "airdate" => "18 Apr 2013", "runtime" => 30, "rating" => 7, "summary" => "Naruto arrives to help a team of Allied Shinobi Forces led by Karui, who are struggling against a reanimated samurai. Naruto recognizes the samurai as Tatewaki, a man he met during a past mission.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/503/1258638.jpg"),
        array("id" => "s2013e16", "season" => 2013, "number" => 16, "name" => "The Fallen Castle", "airdate" => "25 Apr 2013", "runtime" => 30, "rating" => 7, "summary" => "The Leaf Shinobi succeed in bringing young lord Shu into custody, placing a disguised Naruto as his double. But Tatewaki soon uncovers Naruto's identity and surrounds the intruder with his men.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/503/1258907.jpg"),
        array("id" => "s2013e17", "season" => 2013, "number" => 17, "name" => "Prologue of Road to Ninja", "airdate" => "2 May 2013", "runtime" => 30, "rating" => 7.2, "summary" => "Madara is prepping his new jutsu Limited Tsukuyomi, choosing Naruto as his test subject. Meanwhile, Naruto is spending his day off alone in his room. Thinking that Naruto is lonely, Lee suggests they all go to the bathhouse .", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/503/1259269.jpg"),
        array("id" => "s2013e18", "season" => 2013, "number" => 18, "name" => "The Old Master and the Dragon's Eye", "airdate" => "9 May 2013", "runtime" => 30, "rating" => 7.6, "summary" => "Might Guy arrives on the battlefield to stop a Reanimated Shinobi who he recognizes as Master Chen, the legendary Taijutsu User from the Third Great Ninja War.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/503/1259999.jpg"),
        array("id" => "s2013e19", "season" => 2013, "number" => 19, "name" => "Rain Followed by Snow, with Some Lightning", "airdate" => "16 May 2013", "runtime" => 30, "rating" => 7.5, "summary" => "A reanimated boy who can control weather appears before Team Ino-Shika-Cho, Sakura, and Kiba, who are all fighting in different locations. To their surprise, the boy seems to know them.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/504/1260391.jpg"),
        array("id" => "s2013e20", "season" => 2013, "number" => 20, "name" => "The Sad Sun Shower", "airdate" => "23 May 2013", "runtime" => 30, "rating" => 7.2, "summary" => "The weather-controlling enemy is revealed to be Yota, a boy who came to the Leaf Village years ago and befriended the local kids, including Naruto.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/504/1261724.jpg"),
        array("id" => "s2013e21", "season" => 2013, "number" => 21, "name" => "Lingering Snow", "airdate" => "30 May 2013", "runtime" => 30, "rating" => 6.8, "summary" => "Naruto and the others finally regain their lost memories regarding Yota. Years ago, the Leaf Village kids came to befriend Yota, but the adults believed the young boy was a spy and took him away for questioning.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/504/1262248.jpg"),
        array("id" => "s2013e22", "season" => 2013, "number" => 22, "name" => "The Reanimated Allied Forces", "airdate" => "6 Jun 2013", "runtime" => 30, "rating" => 7.8, "summary" => "Kabuto reanimates an army of unknown shinobi led by Danzo's former bodyguard Torune to retrieve the ones he lost to the Allied Forces. But aside from Torune, the reanimated shinobi are all weak and are quickly sealed away.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1262512.jpg"),
        array("id" => "s2013e23", "season" => 2013, "number" => 23, "name" => "Shino vs. Torune!", "airdate" => "13 Jun 2013", "runtime" => 30, "rating" => 8.2, "summary" => "During their battle against the White Zetsu, Shino's beetles detect the presence of another enemy. Leaving the fight to Kiba and the others, Shino goes to investigate and finds Torune preparing to unleash his forbidden jutsu.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1262533.jpg"),
        array("id" => "s2013e24", "season" => 2013, "number" => 24, "name" => "A Hole in the Heart: The Other Jinchūriki", "airdate" => "20 Jun 2013", "runtime" => 30, "rating" => 7.7, "summary" => "Kabuto reanimates Fukai to attack Killer Bee and Motoi. Fukai warns Killer Bee to escape before being taken over by Kabuto. To everyone's surprise, Fukai releases Eight Tails' chakra and enters Tailed Beast State.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1262539.jpg"),
        array("id" => "s2013e25", "season" => 2013, "number" => 25, "name" => "The Soul Living Inside the Puppet", "airdate" => "27 Jun 2013", "runtime" => 30, "rating" => 7.3, "summary" => "A reanimated Granny Chiyo attacks Kankuro and Mifune's team. Kankuro fights back by using the human puppet of Sasori. The sight of Sasori causes Granny Chiyo to recall the painful memories that led her grandson to create his human puppets.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1262808.jpg"),
        array("id" => "s2013e26", "season" => 2013, "number" => 26, "name" => "Run, Omoi!", "airdate" => "4 Jul 2013", "runtime" => 30, "rating" => 6.8, "summary" => "The Allied Forces receive a report that Omoi has deserted his post, much to the Raikage's shock. It is soon revealed that Omoi has defied orders to go save the Thundercloud Unit.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1262818.jpg"),
        array("id" => "s2013e27", "season" => 2013, "number" => 27, "name" => "Reinforcements Arrive", "airdate" => "18 Jul 2013", "runtime" => 30, "rating" => 7.5, "summary" => "White Zetsu's ability to mimic people's appearances has wrought confusion and distrust within the Allied Shinobi Forces. Naruto arrives to assist, and using his sensory powers, he identifies all the disguised White Zetsu clones, changing the tide of the battl…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1263064.jpg"),
        array("id" => "s2013e28", "season" => 2013, "number" => 28, "name" => "Madara Uchiha", "airdate" => "25 Jul 2013", "runtime" => 30, "rating" => 8.3, "summary" => "The reanimated shinobi appearing before Gaara and Ohnoki is revealed to be none other than Madara Uchiha himself…which raises the question of who the masked man claiming to be Madara really is.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1263104.jpg"),
        array("id" => "s2013e29", "season" => 2013, "number" => 29, "name" => "The Five Kage Assembl", "airdate" => "1 Aug 2013", "runtime" => 30, "rating" => 8.1, "summary" => "The power of the reanimated Madara Uchiha far exceeds what the Allied Forces expected. Despite the difference in power, the Third Tsuchikage, Ohnoki, along with Naruto and Gaara, refuses to give up.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1263109.jpg"),
        array("id" => "s2013e30", "season" => 2013, "number" => 30, "name" => "The Unbreakable Mask and the Shattered Bubble", "airdate" => "8 Aug 2013", "runtime" => 30, "rating" => 7.6, "summary" => "Naruto and Killer Bee face off against the masked man originally thought to be Madara Uchiha, in addition to the reanimated Jinchuriki. Naruto is shocked when he recognizes one of the Jinchuriki.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1263147.jpg"),
        array("id" => "s2013e31", "season" => 2013, "number" => 31, "name" => "Jinchuriki vs. Jinchuriki!!", "airdate" => "15 Aug 2013", "runtime" => 30, "rating" => 8.1, "summary" => "Naruto and Killer Bee take on the six Reanimated Jinchuriki, who've been equipped with the Rinnegan. Using his past experience from fighting the Six Paths of Pain, Naruto devises a plan to stop the Jinchuriki", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1263227.jpg"),
        array("id" => "s2013e32", "season" => 2013, "number" => 32, "name" => "Four-Tails, the King of Sage Monkeys", "airdate" => "22 Aug 2013", "runtime" => 30, "rating" => 8.1, "summary" => "Kakashi and Guy arrive in the nick of time to back up Naruto and Killer Bee. The fight intensifies even further when three out of the six Reanimated Jinchuriki enter Tailed Beast State, forcing Naruto and the others to throw in everything they've got.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1263496.jpg"),
        array("id" => "s2013e33", "season" => 2013, "number" => 33, "name" => "Nine Tails", "airdate" => "29 Aug 2013", "runtime" => 30, "rating" => 8, "summary" => "Naruto finds himself inside Four Tails' inner world, where he promises to free Four Tails from Madara's control. Listening in on their conversation, Nine Tails recalls all the time he has spent sealed inside Naruto.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1263499.jpg"),
        array("id" => "s2013e34", "season" => 2013, "number" => 34, "name" => "Kurama", "airdate" => "29 Aug 2013", "runtime" => 30, "rating" => 8, "summary" => "For years, Naruto was the target of Nine Tails' undying hatred. But their time together has made Nine Tails understand Naruto more than anyone. As Naruto continues to try and free Four Tails from Madara's control, Nine Tails begins to undergo a change.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1263500.jpg"),
        array("id" => "s2013e35", "season" => 2013, "number" => 35, "name" => "Two-Man Team", "airdate" => "5 Sep 2013", "runtime" => 30, "rating" => 8, "summary" => "Naruto uses up the last of his chakra trying to free the Tailed Beasts from Madara's control. When all seems lost, the Nine Tails finally acknowledges Naruto as its jinchuriki and offers its help.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1263512.jpg"),
        array("id" => "s2013e36", "season" => 2013, "number" => 36, "name" => "The Promise of Victory", "airdate" => "12 Sep 2013", "runtime" => 30, "rating" => 7.3, "summary" => "The tide of battle is slowly shifting in the Allied Forces' favor, but many are uncertain that they really stand a chance against Madara Uchiha. To help boost their spirits, Shikaku orders Inoichi to send out a message to every member of the forces.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1263513.jpg"),
        array("id" => "s2013e37", "season" => 2013, "number" => 37, "name" => "Eyes That See in the Dark", "airdate" => "19 Sep 2013", "runtime" => 30, "rating" => 7.3, "summary" => "Suigetsu and Jugo's search for Sasuke leads them to one of Orochimaru's old hideouts where they come across his research data, which could tip the outcome of the Fourth Great War. Meanwhile, Sasuke finally sets out to settle his score with Naruto.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1263729.jpg"),
        array("id" => "s2013e38", "season" => 2013, "number" => 38, "name" => "A Will of Stone", "airdate" => "26 Sep 2013", "runtime" => 30, "rating" => 7.7, "summary" => "The Five Kage are outmatched by the real Madara Uchiha's devastating attacks. Just when Third Tsuchikage Ohnoki is about to give up, he remembers the words of the previous Tsuchikage.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1263743.jpg"),
        array("id" => "s2013e39", "season" => 2013, "number" => 39, "name" => "The Risks of the Impure World Reincarnation", "airdate" => "3 Oct 2013", "runtime" => 30, "rating" => 7.7, "summary" => "Tsunade leaves her post as Medic Ninja to join the other Kage in fighting Madara. Meanwhile, Sasuke goes after Itachi and learns that his brother intends on stopping Kabuto's Reanimation Jutsu.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1263753.jpg"),
        array("id" => "s2013e40", "season" => 2013, "number" => 40, "name" => "Sibling Tag Team", "airdate" => "10 Oct 2013", "runtime" => 30, "rating" => 7.7, "summary" => "Sasuke and Itachi team up to stop Kabuto's Reanimation Jutsu. But Kabuto's new ability to use Nature Energy has made him a difficult target for the brothers to land their Susano'o attack.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1263758.jpg"),
        array("id" => "s2013e41", "season" => 2013, "number" => 41, "name" => "To Each Their Own Leaf", "airdate" => "24 Oct 2013", "runtime" => 30, "rating" => 7.7, "summary" => "Kabuto attempts to bring Sasuke over to his side by pointing out that they both are fighting for the same goal: to bring down the Leaf Village. But Sasuke quickly rejects him.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1263764.jpg"),
        array("id" => "s2013e42", "season" => 2013, "number" => 42, "name" => "Kabuto Yakushi", "airdate" => "31 Oct 2013", "runtime" => 30, "rating" => 8, "summary" => "Kabuto's past is finally revealed. As child, a woman named Nonou raised Kabuto at an orphanage in the Leaf Village. One day, Danzo and Orochimaru visit the orphanage to provide financial aid under the condition that Nonou work as their spy.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1264679.jpg"),
        array("id" => "s2013e43", "season" => 2013, "number" => 43, "name" => "The Izanami Activated", "airdate" => "7 Nov 2013", "runtime" => 30, "rating" => 7.8, "summary" => "Kabuto's quest to discover his true identity has led him over the years to collect, analyze, and use the abilities of all shinobi within him, including Kimimaro, the Sound Four and Orochimaru.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/505/1264681.jpg"),
        array("id" => "s2013e44", "season" => 2013, "number" => 44, "name" => "Izanagi and Izanami", "airdate" => "14 Nov 2013", "runtime" => 30, "rating" => 7.5, "summary" => "Itachi activates the Visual Jutsu Izanami to trap Kabuto's mind. Itachi then explains to Sasuke how Izanami was originally developed to keep the Uchiha from abusing the power of Izanagi.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/506/1265579.jpg"),
        array("id" => "s2013e45", "season" => 2013, "number" => 45, "name" => "I Will Love You Always", "airdate" => "21 Nov 2013", "runtime" => 30, "rating" => 7.9, "summary" => "The Five Kage watch helplessly as Madara activates his Perfect Susano'o to destroy them. Meanwhile, Itachi succeeds in undoing Kabuto's Reanimation Jutsu. Before fading away, Itachi reveals to Sasuke the truth behind the Uchiha massacre.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/506/1265650.jpg"),
        array("id" => "s2013e46", "season" => 2013, "number" => 46, "name" => "Impure World Reincarnation: Release!", "airdate" => "28 Nov 2013", "runtime" => 30, "rating" => 7.9, "summary" => "Thanks to Itachi, the Reanimation Jutsu is released, and all the Reanimated Shinobi are returned to their resting places. But to everyone's surprise, the real Madara still remains!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/506/1265666.jpg"),
        array("id" => "s2013e47", "season" => 2013, "number" => 47, "name" => "Orochimaru's Return", "airdate" => "5 Dec 2013", "runtime" => 30, "rating" => 7.3, "summary" => "Suigetsu and Jugo finally catch up to Sasuke. In order to learn the truth behind the Leaf's actions, Sasuke decides to resurrect the one man who can help him find the answer—Orochimaru.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/506/1266017.jpg"),
        array("id" => "s2013e48", "season" => 2013, "number" => 48, "name" => "The Secret of the Transportation Technique", "airdate" => "12 Dec 2013", "runtime" => 30, "rating" => 8, "summary" => "Having absorbed the chakras of all nine Tailed Beasts, the Gedo Statue begins its transformation into Ten Tails. Naruto, Killer Bee, Kakashi, and Guy try to destroy the Gedo Statue but are stopped by the masked man who is able to phase through all of their at…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/506/1266020.jpg"),
        array("id" => "s2013e49", "season" => 2013, "number" => 49, "name" => " Who Are You?", "airdate" => "19 Dec 2013", "runtime" => 30, "rating" => 7.9, "summary" => "Kakashi is disturbed to discover a strange connection between the masked man's Transportation Technique and his own Kamui Jutsu. Naruto throws everything he's got against the masked man and succeeds in shattering his mask. The identity of the masked man is fi…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/506/1266072.jpg"),
    )),
