        array("id" => "s2014e8", "season" => 2014, "number" => 8, "name" => "Hashirama's Cells", "airdate" => "20 Feb 2014", "runtime" => 30, "rating" => 7.5, "summary" => "At the Foundation, Kakashi meets a boy who uses Wood Style, a jutsu that only First Hokage Hashirama was capable of using. Kakashi goes to Third Hokage Hiruzen's library to seek answers and discovers records regarding Hashirama's cells.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/507/1268494.jpg"),
