        array("id" => "s2014e10", "season" => 2014, "number" => 10, "name" => "Orochimaru's Test Subject", "airdate" => "6 Mar 2014", "runtime" => 30, "rating" => 7.2, "summary" => "While pursuing Orochimaru, Kakashi wanders into a village inhabited by the Iburi Clan, a group of people with the unique ability to turn into smoke. Kakashi is soon captured and learns that the villagers all serve under Orochimaru.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/60/150158.jpg"),
        array("id" => "s2014e11", "season" => 2014, "number" => 11, "name" => "Their Own Paths", "airdate" => "6 Mar 2014", "runtime" => 30, "rating" => 7, "summary" => "Yukimi leaves the village to see the outside world, taking \"Tenzo\" with her. Kakashi tries to convince the two to return so that he can set a trap to capture Orochimaru, who is after Yukimi's blood. But Yamato, who has grown attached to Yukimi, abandons his o…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/507/1269042.jpg"),
        array("id" => "s2014e12", "season" => 2014, "number" => 12, "name" => "The Targeted Sharingan", "airdate" => "13 Mar 2014", "runtime" => 30, "rating" => 7.3, "summary" => "Danzo orders Tenzo to kill Kakashi and take his Sharingan. Reluctant at first, Tenzo decides to carry out his orders after learning that the Leaf Shinobi has come to be known as \"Kakashi the Friend Killer.\"", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/507/1269110.jpg"),
