        array("id" => "s2014e14", "season" => 2014, "number" => 14, "name" => "An Uchiha ANBU", "airdate" => "3 Apr 2014", "runtime" => 30, "rating" => 7.3, "summary" => "Itachi Uchiha is inducted into Kakashi's unit as the youngest member of the ANBU Black Ops. Itachi's father, Fugaku, is pleased, thinking this will grant the Uchiha access to exclusive, top-secret Leaf intel. But Danzo, who wants intel on the Uchiha, orders I…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/507/1269336.jpg"),
        array("id" => "s2014e15", "season" => 2014, "number" => 15, "name" => "Coup d'État", "airdate" => "10 Apr 2014", "runtime" => 30, "rating" => 7.5, "summary" => "Following the aftermath of the Nine-Tails incident, many on the Leaf Council voice suspicions that the Uchiha Clan were behind this tragedy. The Uchiha are then placed under 24-hour surveillance by the ANBU, which causes further tensions to arise.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/507/1269890.jpg"),
        array("id" => "s2014e16", "season" => 2014, "number" => 16, "name" => "The Night of the Tragedy", "airdate" => "17 Apr 2014", "runtime" => 30, "rating" => 7.3, "summary" => "Kakashi visits the Uchiha District and notices that the community seems more antisocial than the last time he visited. Meanwhile Itachi finds concrete evidence regarding the Uchiha Clan's coup against the Leaf. The fateful moment is fast approaching…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/508/1270097.jpg"),
