        array("id" => "s2014e23", "season" => 2014, "number" => 23, "name" => "The All-Knowing", "airdate" => "19 Jun 2014", "runtime" => 30, "rating" => 7.7, "summary" => "Sasuke returns to the Hidden Leaf Village seeking answers, and standing before him are First Hokage Hashirama, Second Hokage Tobirama, Third Hokage Hiruzen, and Fourth Hokage Minato, all reanimated.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/508/1270458.jpg"),
